const root=resolve('.codex-temp/google-play-performance-20261021/web'),out=resolve(`.codex-temp/google-play-performance-20261021/input-${Date.now()}`);await mkdir(out,{recursive:true});
const compiled=await build({stdin:{contents:"export {LEVELS} from './src/core/levels.ts';export {solveLevelForValidation} from './src/core/levelSolver.ts';",resolveDir:process.cwd()},bundle:true,format:'esm',platform:'node',write:false,logLevel:'silent'});
