 await context.addInitScript(()=>{const memory=new Map(),storage=map=>({getItem:k=>map.get(String(k))??null,setItem:(k,v)=>map.set(String(k),String(v)),removeItem:k=>map.delete(String(k)),clear:()=>map.clear(),key:i=>[...map.keys()][i]??null,get length(){return map.size;}});Object.defineProperty(window,'localStorage',{value:storage(memory)});Object.defineProperty(window,'sessionStorage',{value:storage(new Map())});window.__memoryOnly=memory;for(const name of ['getItem','setItem','clear','removeItem','key'])Storage.prototype[name]=()=>{throw Error('Persistent storage forbidden');};for(const name of ['open','deleteDatabase'])indexedDB[name]=()=>{throw Error('IndexedDB forbidden');};});
 const page=await context.newPage(),cdp=await context.newCDPSession(page),row={viewport,errors:[],actions:[]};report.runs.push(row);page.on('pageerror',e=>row.errors.push(String(e)));await page.goto(origin);await page.waitForFunction(()=>{const s=window.__COLOR_ESCAPE__?.getDebugState();return s?.art.ready&&s.screen==='playing';},undefined,{timeout:30000});
 const state=()=>page.evaluate(()=>window.__COLOR_ESCAPE__.getDebugState());let current=await state();assert.equal(current.puzzle.levelId,1);assert.deepEqual(current.level,JSON.parse(JSON.stringify(api.LEVELS[0])));
